use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut i: int = 0
    while i < keys.len() {
        if keys[i] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(keys.clone(), k)
            if i >= 0 {
                keys.remove(i)
                vals.remove(i)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() > cap {
                let last = keys.len() - 1
                let ek = keys[last]
                keys.remove(last)
                vals.remove(last)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(keys.clone(), k)
            if i < 0 {
                println("-1")
            } else {
                let v = vals[i]
                keys.remove(i)
                vals.remove(i)
                keys.insert(0, k)
                vals.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let strs: Vec<string> = keys.map(|x| "${x}").collect()
                println(strs.join(" "))
            }
        }
    }
}

